void AcidTheme::drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float p,float a,float b,juce::Slider&){float size=(float)juce::jmin(w,h)-15;auto r=juce::Rectangle<float>((float)x+(w-size)*.5f,(float)y+(h-size)*.5f,size,size);auto c=r.getCentre();float radius=size*.5f;g.setColour(juce::Colours::black.withAlpha(.25f));g.fillEllipse(r.translated(2,4).expanded(2));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff747a7d),r.getTopLeft(),juce::Colour(0xff151718),r.getBottomRight(),false));g.fillEllipse(r);g.setColour(juce::Colour(0xff353d37));g.drawEllipse(r,1);auto inside=r.reduced(5);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff474b4e),inside.getTopLeft(),juce::Colour(0xff141719),inside.getBottomRight(),false));g.fillEllipse(inside);for(int i=0;i<=10;i++){float t=a+(b-a)*i/10.f;g.setColour(juce::Colour(0xffffedcf));g.drawLine(c.x+std::sin(t)*(radius+3),c.y-std::cos(t)*(radius+3),c.x+std::sin(t)*(radius+6),c.y-std::cos(t)*(radius+6),1);}float angle=a+(b-a)*p;g.setColour(juce::Colour(0xffffe2a0));g.drawLine(c.x+std::sin(angle)*radius*.25f,c.y-std::cos(angle)*radius*.25f,c.x+std::sin(angle)*radius*.76f,c.y-std::cos(angle)*radius*.76f,2.5f);}
AcidControl::AcidControl(juce::AudioProcessorValueTreeState&state,acid::Param id){auto&s=acid::specs[(size_t)id];addAndMakeVisible(label);label.setText(s.name,juce::dontSendNotification);label.setJustificationType(juce::Justification::centred);label.setFont(juce::Font(12.f,juce::Font::bold));if(s.choices[0]){addAndMakeVisible(combo);combo.addItemList(juce::StringArray::fromTokens(s.choices,"|",""),1);ca=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(state,s.id,combo);}else{addAndMakeVisible(knob);knob.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);knob.setTextBoxStyle(juce::Slider::TextBoxBelow,false,72,20);knob.setDoubleClickReturnValue(true,s.initial);knob.setName(s.name);sa=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(state,s.id,knob);}}
void AcidControl::resized(){auto r=getLocalBounds();label.setBounds(r.removeFromTop(20));if(ca)combo.setBounds(r.reduced(4,juce::jmax(1,(r.getHeight()-28)/2)));else knob.setBounds(r.reduced(4));}
void StepGrid::paint(juce::Graphics&g){auto p=processor.getPattern(processor.selectedPattern());const int activeStep=processor.playStep.load();float label=58,cw=(getWidth()-label)/16.f;float top=28,ph=(getHeight()-top-108)/24.f;const char* notes[]={"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"};g.fillAll(juce::Colour(0xff30382f));g.setColour(juce::Colour(0xffc8cdc4));g.fillRect(juce::Rectangle<float>(0.f,0.f,(float)getWidth(),28.f));g.fillRect(juce::Rectangle<float>(0.f,28.f,58.f,(float)getHeight()-28.f));g.setFont(11.f);
 for(int i=0;i<16;i++){float x=label+i*cw;if(i==activeStep){g.setColour(juce::Colour(0xff151b1f));g.fillRect(juce::Rectangle<float>(x,0.f,cw,26.f));}g.setColour(i==activeStep?juce::Colour(0xffffed00):juce::Colours::black);g.setFont(juce::Font(i==activeStep?15.f:11.f,juce::Font::bold));g.drawText(juce::String(i+1),(int)x,0,(int)cw,24,juce::Justification::centred);for(int row=0;row<24;row++){int note=59-row;float y=top+row*ph;bool selected=p[(size_t)i].gate&&p[(size_t)i].note==note;g.setColour(selected?(p[(size_t)i].accent?juce::Colour(0xffb65025):juce::Colour(0xff764b30)):(note%12==1||note%12==3||note%12==6||note%12==8||note%12==10?juce::Colour(0xffafb4a1):juce::Colour(0xffd1d3bd)));g.fillRect(juce::Rectangle<float>(x+1.f,y+1.f,cw-2.f,ph-1.f));}}
 g.setFont(11.f);for(int row=0;row<24;row++){int note=59-row;g.setColour(juce::Colours::black);g.drawText(juce::String(notes[note%12])+juce::String(note/12-1),0,(int)(top+row*ph),50,(int)ph,juce::Justification::centredRight);}
 const char* names[]={"GATE","ACCENT","SLIDE","VIBRATO"};for(int row=0;row<4;row++){float y=top+24*ph+row*27;g.setColour(juce::Colours::black);g.drawText(names[row],0,(int)y,54,26,juce::Justification::centredRight);for(int i=0;i<16;i++){auto&s=p[(size_t)i];bool flag=row==0?s.gate:(row==1?s.accent:(row==2?s.slide:s.vibrato));g.setColour(flag?(row==1?accent:juce::Colour(0xff688b82)):juce::Colour(0xffa8b09b));g.fillRect(juce::Rectangle<float>(label+i*cw+1.f,y+2.f,cw-2.f,23.f));}}
 if(activeStep>=0&&activeStep<16){float x=label+activeStep*cw;auto column=juce::Rectangle<float>(x+1.f,top,cw-2.f,(float)getHeight()-top-1.f);g.setColour(juce::Colour(0xffffed00).withAlpha(.24f));g.fillRect(column);g.setColour(juce::Colour(0xffffed00));g.drawRect(column,3.f);g.fillRect(juce::Rectangle<float>(x+1.f,24.f,cw-2.f,4.f));auto& step=p[(size_t)activeStep];if(step.gate&&step.note>=36&&step.note<=59){float y=top+(59-step.note)*ph;g.setColour(juce::Colours::black);g.drawRect(juce::Rectangle<float>(x+4.f,y+1.f,cw-8.f,ph-1.f),2.f);}}

}
void StepGrid::mouseDown(const juce::MouseEvent&e){float cw=(getWidth()-58)/16.f,ph=(getHeight()-28-108)/24.f;int i=(int)((e.position.x-58)/cw);if(e.position.x<58||i<0||i>15||e.position.y<28)return;int bank=processor.selectedPattern();auto p=processor.getPattern(bank);auto&s=p[(size_t)i];if(e.position.y<28+24*ph){int n=59-juce::jlimit(0,23,(int)((e.position.y-28)/ph));if(s.note==n)s.gate=!s.gate;else{s.note=n;s.gate=true;}}else{int row=(int)((e.position.y-28-24*ph)/27);if(row==0)s.gate=!s.gate;else if(row==1)s.accent=!s.accent;else if(row==2)s.slide=!s.slide;else if(row==3)s.vibrato=!s.vibrato;}processor.setStep(bank,i,s);repaint();}
AcidEditor::AcidEditor(AcidProcessor&p):AudioProcessorEditor(p),processor(p),grid(p){setLookAndFeel(&theme);viewport.setViewedComponent(&body,false);viewport.setScrollBarsShown(true,true);addAndMakeVisible(viewport);for(int i=0;i<acid::Count;i++){auto c=std::make_unique<AcidControl>(p.state,(acid::Param)i);body.addAndMakeVisible(*c);controls.push_back(std::move(c));}body.addAndMakeVisible(grid);for(auto*c:std::initializer_list<juce::Component*>{&scenes,&previousPatch,&nextPatch,&run,&panic,&save,&load,&exportMidi,&copy,&paste,&clear,&random,&left,&right,&status})body.addAndMakeVisible(*c);
 for(int i=0;i<256;i++)scenes.addItem(juce::String::fromUTF8(acid::scenes[(size_t)i].name),i+1);scenes.setSelectedId(1,juce::dontSendNotification);scenes.onChange=[this]{processor.setCurrentProgram(scenes.getSelectedId()-1);};previousPatch.setTooltip("Previous patch");nextPatch.setTooltip("Next patch");previousPatch.onClick=[this]{int count=processor.getNumPrograms();int index=(processor.getCurrentProgram()+count-1)%count;processor.setCurrentProgram(index);selectedScene=index;scenes.setSelectedId(index+1,juce::dontSendNotification);grid.repaint();};nextPatch.onClick=[this]{int count=processor.getNumPrograms();int index=(processor.getCurrentProgram()+1)%count;processor.setCurrentProgram(index);selectedScene=index;scenes.setSelectedId(index+1,juce::dontSendNotification);grid.repaint();};run.onClick=[this]{processor.running.store(!processor.running.load());};panic.onClick=[this]{processor.panic.store(true);};copy.onClick=[this]{clipboard=processor.getPattern(processor.selectedPattern());copied=true;};paste.onClick=[this]{if(copied)processor.putPattern(processor.selectedPattern(),clipboard);grid.repaint();};clear.onClick=[this]{auto p=processor.getPattern(processor.selectedPattern());for(auto&s:p)s.gate=false;processor.putPattern(processor.selectedPattern(),p);grid.repaint();};
 random.onClick=[this]{std::mt19937 rng((uint32_t)juce::Time::getMillisecondCounter());auto p=processor.getPattern(processor.selectedPattern());const int scale[]={0,3,5,7,10,12,15,17};for(auto&s:p){s.note=36+scale[rng()%8];s.gate=rng()%5!=0;s.accent=rng()%4==0;s.slide=rng()%5==0;s.vibrato=rng()%7==0;}processor.putPattern(processor.selectedPattern(),p);grid.repaint();};
 left.onClick=[this]{auto p=processor.getPattern(processor.selectedPattern());std::rotate(p.begin(),p.begin()+1,p.end());processor.putPattern(processor.selectedPattern(),p);grid.repaint();};right.onClick=[this]{auto p=processor.getPattern(processor.selectedPattern());std::rotate(p.rbegin(),p.rbegin()+1,p.rend());processor.putPattern(processor.selectedPattern(),p);grid.repaint();};
 const juce::Component::SafePointer<AcidEditor> guard(this);
 save.onClick=[this,guard]{chooser=std::make_unique<juce::FileChooser>("Save Acid VOG patch",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("My Acid Patch.vacid"),"*.vacid");chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[guard](const juce::FileChooser&f){if(guard&&f.getResult()!=juce::File()){juce::MemoryBlock b;guard->processor.getStateInformation(b);if(!f.getResult().withFileExtension("vacid").replaceWithData(b.getData(),b.getSize()))guard->status.setText("Patch save failed",juce::dontSendNotification);}});};
 load.onClick=[this,guard]{chooser=std::make_unique<juce::FileChooser>("Load Acid VOG patch",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*.vacid");chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[guard](const juce::FileChooser&f){if(guard){juce::MemoryBlock b;if(f.getResult().loadFileAsData(b))guard->processor.setStateInformation(b.getData(),(int)b.getSize());}});};
 exportMidi.onClick=[this,guard]{chooser=std::make_unique<juce::FileChooser>("Export pattern MIDI",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("Acid Pattern.mid"),"*.mid");chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[guard](const juce::FileChooser&f){if(guard&&f.getResult()!=juce::File())guard->exportPattern(f.getResult().withFileExtension("mid"));});};
 setResizable(true,true);setResizeLimits(1100,760,2000,1400);setSize(1600,1000);startTimerHz(25);
}
