void AcidSurface::paint(juce::Graphics&g){if(getWidth()<=0||getHeight()<=0)return;if(!woodTexture.isValid()||woodTexture.getWidth()!=getWidth()||woodTexture.getHeight()!=getHeight()){woodTexture=juce::Image(juce::Image::RGB,getWidth(),getHeight(),true);juce::Graphics t(woodTexture);t.setGradientFill(juce::ColourGradient(juce::Colour(0xffa07850),0,0,juce::Colour(0xff715033),0,(float)getHeight(),false));t.fillRect(juce::Rectangle<int>(0,0,getWidth(),getHeight()));for(int y=-10;y<getHeight()+10;y+=2){juce::Path grain;grain.startNewSubPath(0.f,(float)y);for(int x=0;x<=getWidth()+24;x+=24){float wave=2.2f*std::sin(x*.009f+y*.047f)+1.2f*std::sin(x*.024f+y*.11f);grain.lineTo((float)x,y+wave);}t.setColour(juce::Colour(0xff775126).withAlpha(.055f+.035f*(.5f+.5f*std::sin(y*.37f))));t.strokePath(grain,juce::PathStrokeType(.7f));}for(int y=9;y<getHeight();y+=17){t.setColour(juce::Colour(0xffffedc4).withAlpha(.06f));t.drawHorizontalLine(y,0.f,(float)getWidth());}}g.drawImageAt(woodTexture,0,0);g.setColour(juce::Colour(0xffffedcf));g.setFont(juce::Font(33.f,juce::Font::bold));g.drawText("ACID VOG",getWidth()-460,20,310,45,juce::Justification::centredLeft);g.setFont(12.f);g.drawText("1.0.8 STABILITY UPDATE  /  BASS SEQUENCER",getWidth()-460,65,370,20,juce::Justification::centredLeft);g.setFont(juce::Font(14.f,juce::Font::bold));g.drawText("SCENE / 256 PATCHES",26,12,300,22,juce::Justification::centredLeft);g.drawText("VOICE / MODULATION",24,92,350,24,juce::Justification::centredLeft);g.drawText("DISTORTION / COLOR",24,276,400,24,juce::Justification::centredLeft);g.drawText("CHORUS / ECHO / REVERB",510,276,650,24,juce::Justification::centredLeft);g.drawText("OUTPUT",getWidth()-126,276,106,24,juce::Justification::centred);g.drawText("PATTERN EDITOR",24,446,300,22,juce::Justification::centredLeft);g.drawText("CLOCK / PLAY MODE",getWidth()-330,502,300,24,juce::Justification::centredLeft);g.setColour(juce::Colour(0xff7c887d));for(int y:{88,270,440})g.drawHorizontalLine(y,18,(float)getWidth()-18);g.drawVerticalLine(496,276,438);g.drawVerticalLine(getWidth()-145,276,438);float peak=(float)getProperties().getWithDefault("peak",0.f);g.setColour(ink);g.fillRect(getWidth()-125,434,104,5);g.setColour(peak>.95f?juce::Colours::red:accent);g.fillRect(getWidth()-125,434,(int)(104*juce::jlimit(0.f,1.f,peak)),5);}
void AcidEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff302015));for(int side=0;side<2;side++){float x=side==0?0.f:(float)getWidth()-24.f;g.setGradientFill(juce::ColourGradient(juce::Colour(0xff24150f),x,0,juce::Colour(0xff63432a),x+24.f,0,false));g.fillRect(juce::Rectangle<float>(x,0.f,24.f,(float)getHeight()));for(int k=0;k<14;k++){juce::Path grain;grain.startNewSubPath(x+k*1.8f,0.f);for(int y=0;y<=getHeight();y+=20)grain.lineTo(x+k*1.8f+1.2f*std::sin(y*.018f+k*.7f),(float)y);g.setColour(juce::Colours::black.withAlpha(.24f));g.strokePath(grain,juce::PathStrokeType(.7f));}}for(int edge=0;edge<2;edge++){float y=edge==0?0.f:(float)getHeight()-10.f;juce::ColourGradient gold(juce::Colour(0xff72511a),0,y,juce::Colour(0xffa57828),0,y+10.f,false);gold.addColour(.24,juce::Colour(0xffffe89f));gold.addColour(.55,juce::Colour(0xffcca34e));gold.addColour(.78,juce::Colour(0xffead28b));g.setGradientFill(gold);g.fillRect(juce::Rectangle<float>(0.f,y,(float)getWidth(),10.f));}}
void AcidEditor::timerCallback(){run.setButtonText(processor.running.load()?"STOP / ARMED":"START / ARM");if(selectedScene!=processor.getCurrentProgram()){selectedScene=processor.getCurrentProgram();scenes.setSelectedId(selectedScene+1,juce::dontSendNotification);}grid.repaint();status.setText((processor.protectionTrips.load()>0?juce::String("OUTPUT GUARD: ")+juce::String((juce::int64)processor.protectionTrips.load())+" resets  •  ":juce::String())+juce::String(processor.bpmDisplay.load(),1)+" BPM  •  Click a note cell to set/toggle a step  •  SLIDE ties into the marked step  •  Clock: Internal or DAW transport",juce::dontSendNotification);body.getProperties().set("peak",processor.peak.load());body.repaint();}
void AcidEditor::exportPattern(const juce::File&file){auto val=[this](acid::Param p){return processor.state.getRawParameterValue(acid::specs[p].id)->load();};auto p=processor.getPattern(processor.selectedPattern());int length=(int)val(acid::Length);double bpm=processor.bpmDisplay.load();const double beats[]={.5,.25,1.0/6,.125};double unit=beats[(size_t)(int)val(acid::Rate)];juce::MidiMessageSequence seq;seq.addEvent(juce::MidiMessage::tempoMetaEvent((int)(60000000/std::max(20.0,bpm))),0);for(int i=0;i<length;i++)if(p[(size_t)i].gate){double start=(i+(i%2?val(acid::Swing)*.01:0))*unit*960;double dur=unit*(i%2?1-val(acid::Swing)*.01:1+val(acid::Swing)*.01)*val(acid::Gate)*.01*960;auto&s=p[(size_t)i];int note=juce::jlimit(0,127,s.note+(int)val(acid::Transpose));seq.addEvent(juce::MidiMessage::noteOn(1,note,(juce::uint8)(s.accent?120:88)),start);seq.addEvent(juce::MidiMessage::noteOff(1,note),start+dur);}seq.updateMatchedPairs();juce::MidiFile midi;midi.setTicksPerQuarterNote(960);midi.addTrack(seq);juce::FileOutputStream stream(file);if(stream.openedOk()){stream.setPosition(0);stream.truncate();if(!midi.writeTo(stream))status.setText("MIDI export failed",juce::dontSendNotification);}}
